  const handleSubmit = (values: FormValues) => new Promise<void>(resolve => {
    setTimeout(() => {
      alert(JSON.stringify(values, null, 2));
      resolve();
    }, 1000);
  });
  const {
    form,
    currentStepId,
    steps,
    isFirstStep,
    isLastStep,
    onClickStep,
    onPrevStep,
    onSubmit
  } = useFormWizard({
    steps: [{
      id: 'stepOne',
      label: 'Личные данные',
      validationSchema: validationSchemaStepOne,
      component: StepOne
    }, {
      id: 'stepTwo',
      label: 'Контактные данные',
      validationSchema: validationSchemaStepTwo,
      component: StepTwo
    }],
    onSubmit: handleSubmit
  });
  const {
    isSaving,
    isSendMail,
    handleSaving,
    handleSendMail
  } = useMockWizardForm();
  return <MockWrapper>
      <FormWizardPageLayout<FormValues> header={{
      title: 'Создание доверенности',
      actions: {
        main: [{
          text: 'Сохранить',
          variant: 'outlined',
          color: 'grey',
          loading: isSaving,
          isBlockingOperation: true,
          onClick: handleSaving
        }, {
          text: 'Добавить по номеру',
          startIcon: <AddOutlineMd />,
          popoverProps: {
            title: 'Добавить по номеру'
          },
          variant: 'outlined',
          color: 'grey',
          isNested: true,
          actions: [{
            text: 'Из реестра ЦПРР'
          }, {
            text: 'Из реестра СФР'
          }]
        }]
      }
    }} formWizard={{
      form,
      currentStepId,
      steps,
      isFirstStep,
      isLastStep,
      submitButtonText: 'Подписать',
      secondaryActions: [{
        text: 'Отправить на почту',
        isBlockingOperation: true,
        loading: isSendMail,
        onClick: handleSendMail
      }],
      onClickStep,
      onPrevStep,
      onSubmit
    }} />
    </MockWrapper>;
